HAL_FLASHEx_Erase.exampleCode:
uint32_t page_error = 0;
FLASH_EraseInitTypeDef erase = {0};

erase.TypeErase   = FLASH_TYPEERASE_PAGES;
erase.PageAddress = 0x0801F000;   /* 目标页起始地址 */
erase.NbPages     = 1;

if (HAL_FLASHEx_Erase(&erase, &page_error) != HAL_OK)
{
  /* page_error 是出错的页号，0xFFFFFFFF 表示全部成功 */
}

HAL_FLASH_Program.exampleCode:
/* 写入前必须确保该地址已擦除（0xFFFF） */
HAL_FLASH_Program(FLASH_TYPEPROGRAM_WORD,   /* 32 位编程 */
                  0x0801F000,
                  0x12345678);

HAL_FLASH_Unlock.exampleCode:
HAL_FLASH_Unlock();

/* 擦除 + 写入（详见 HAL_FLASHEx_Erase / HAL_FLASH_Program） */
uint32_t page_error = 0;
FLASH_EraseInitTypeDef erase = {0};
erase.TypeErase   = FLASH_TYPEERASE_PAGES;
erase.PageAddress = 0x0801F000;
erase.NbPages     = 1;
HAL_FLASHEx_Erase(&erase, &page_error);

/* F1 只支持半字或字编程 */
HAL_FLASH_Program(FLASH_TYPEPROGRAM_WORD, 0x0801F000, 0x12345678);

HAL_FLASH_Lock();
